-- A meditation that sits in a volume no longer sits straight in the album
-- (a database seeded before volumes had it there).
delete from public.library_relations x
using public.library_resources t, public.library_resources a
where x.kind = 'part-of' and x.from_id = t.id and x.to_id = a.id and a.type = 'album'
  and exists (select 1 from public.library_relations y join public.library_resources v on v.id = y.to_id
              where y.from_id = t.id and y.kind = 'part-of' and v.type = 'volume');

insert into public.library_collections (slug, title, blurb, by_line, time_line, status, sort) values
  ('first-week', 'A first week of meditation', 'For someone who has never meditated, or stopped a long time ago. Relax first, then keep the day’s two ends.', 'Suggested by the Hermitage', '5 recordings, then a class', 'published', 0),
  ('hard-season', 'Through a hard season', 'For illness, grief, or a difficult person: your own healing first, then the people around you.', 'Suggested by the Hermitage', '6 recordings', 'published', 1),
  ('praying-text', 'Praying with a text', 'Justin taught that any familiar text, scripture, poem or prayer can become a meditation. These follow his path from spoken prayer toward silence.', 'Suggested by the Hermitage', '7 recordings, then a retreat', 'published', 2),
  ('sfl-four-ways', 'Success: Full Living, four ways', 'Justin’s flagship teaching comes in four forms. Take the one that fits how you learn, or all four in turn.', 'Suggested by the Hermitage', 'A book, an album, a series, a program', 'published', 3)
on conflict (slug) do nothing;

insert into public.library_collection_items (collection_id, resource_id, sort, note)
select c.id, r.id, v.sort, v.note from (values
  ('first-week', 't-relaxation', 0, 'Start here, especially if relaxing doesn’t come easily.'),
  ('first-week', 't-universal-am', 1, 'Made for people of any faith. Light stands for God.'),
  ('first-week', 't-universal-pm', 2, 'Its evening companion. Keep both ends of the day.'),
  ('first-week', 't-contemplative-am', 3, 'When you are ready to be led less and to rest more.'),
  ('first-week', 'train-your-mind', 4, 'When you want to practice with others, and know why it works.'),
  ('hard-season', 't-healing-self', 0, 'For whatever is unwell: body, mind, feeling or spirit.'),
  ('hard-season', 't-healing-others-1', 1, 'If it is someone you love who is ill.'),
  ('hard-season', 't-relationships-1', 2, 'For the person who is hardest to be with.'),
  ('hard-season', 't-self-image', 3, 'How the picture we carry of ourselves is made.'),
  ('hard-season', 't-affirmations', 4, 'And how to begin remaking it.'),
  ('hard-season', 't-peace-1', 5, 'Widening out: peace, at the largest scale.'),
  ('praying-text', 't-st-francis', 0, 'The first example: a prayer many people already know.'),
  ('praying-text', 't-lords-prayer', 1, 'The second: the prayer Jesus taught.'),
  ('praying-text', 't-psalm-23', 2, 'The same way of listening, with a psalm.'),
  ('praying-text', 't-canticle', 3, 'And with St. Francis’s praise of creation.'),
  ('praying-text', 't-creation', 4, 'The heart of Franciscan spirituality: the Creation Model.'),
  ('praying-text', 't-serenity', 5, 'Creation Spirituality brought to a prayer for everyday life.'),
  ('praying-text', 'deep-peace', 6, 'Where the path leads: a whole day of silence.'),
  ('sfl-four-ways', 'sfl-book', 0, 'To read at your own pace.'),
  ('sfl-four-ways', 'sfl-album', 1, 'As a mini-retreat at home, on three discs.'),
  ('sfl-four-ways', 'sfl-series', 2, 'To hear Justin teach it himself.'),
  ('sfl-four-ways', 'sfl-program', 3, 'To work through it with others.')
) as v (collection, resource, sort, note)
join public.library_collections c on c.slug = v.collection
join public.library_resources r on r.slug = v.resource
on conflict do nothing;
